#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MOD 998244353LL
#define MAXB 61

typedef long long ll;
typedef unsigned long long ull;

static ll modpow(ll a, ll e) {
    ll r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

static int cmp_ull(const void *a, const void *b) {
    ull x = *(const ull*)a, y = *(const ull*)b;
    if (x < y) return -1;
    if (x > y) return 1;
    return 0;
}

int main(void) {
    int N;
    ull X;
    if (scanf("%d %llu", &N, &X) != 2) return 0;

    ull *A = (ull*)malloc(sizeof(ull) * N);
    for (int i = 0; i < N; i++) scanf("%llu", &A[i]);

    qsort(A, N, sizeof(ull), cmp_ull);

    ull basis[MAXB];
    memset(basis, 0, sizeof(basis));
    int rank = 0;

    for (int i = 0; i < N; i++) {
        ull v = A[i];
        for (int b = MAXB - 1; b >= 0; b--) {
            if (((v >> b) & 1ULL) == 0) continue;
            if (basis[b]) {
                v ^= basis[b];
            } else {
                basis[b] = v;
                rank++;
                break;
            }
        }
    }

    ull reduced[MAXB];
    memset(reduced, 0, sizeof(reduced));
    for (int b = 0; b < MAXB; b++) reduced[b] = basis[b];

    for (int i = MAXB - 1; i >= 0; i--) {
        if (!reduced[i]) continue;
        for (int j = i - 1; j >= 0; j--) {
            if (reduced[j] && ((reduced[i] >> j) & 1ULL)) {
                reduced[i] ^= reduced[j];
            }
        }
    }

    int pivots[MAXB], pcnt = 0;
    for (int b = 0; b < MAXB; b++) {
        if (reduced[b]) pivots[pcnt++] = b;
    }

    int indep[MAXB];
    memset(indep, 0, sizeof(indep));
    for (int i = 0; i < pcnt; i++) indep[pivots[i]] = 1;

    ll ans = 0;
    int used = 0;

    for (int b = MAXB - 1; b >= 0; b--) {
        if (((X >> b) & 1ULL) == 0) {
            if (indep[b]) used++;
            continue;
        }

        if (indep[b]) {
            ans = (ans + modpow(2, rank - used - 1)) % MOD;
            used++;
        } else {
            ans = (ans + modpow(2, rank - used)) % MOD;
        }
    }

    ull y = X;
    for (int b = MAXB - 1; b >= 0; b--) {
        if (!((y >> b) & 1ULL)) continue;
        if (reduced[b]) y ^= reduced[b];
    }
    if (y == 0) ans = (ans + 1) % MOD;

    printf("%lld\n", ans % MOD);

    free(A);
    return 0;
}

