const int MOD = 998244353;

long long gf2_mod(long long a, long long g) {
    if (g == 0) return a;
    int dg = 63 - __builtin_clzll(g);
    while (a >= g) {
        if (a == 0) break;
        int da = 63 - __builtin_clzll(a);
        if (da < dg) break;
        a ^= (g << (da - dg));
    }
    return a;
}

long long gf2_gcd(long long a, long long b) {
    while (b) { long long t = gf2_mod(a, b); a = b; b = t; }
    return a;
}

int main(){
    int n; long long X;
    cin >> n >> X;
    long long g = 0;
    for (int i = 0; i < n; i++) { long long a; cin >> a; g = gf2_gcd(g, a); }
    // count v in [0,X] with gf2_mod(v,g)==0
    // digit DP on bits of X
    int B = 62;
    // dp[tight][rem] = count
    // rem has at most 2^deg(g) values
    int dg = (g == 0) ? 0 : (63 - __builtin_clzll(g));
    int sz = (g == 0) ? 1 : (1 << dg);
    vector<vector<long long>> dp(2, vector<long long>(sz, 0));
    dp[1][0] = 1;
    for (int bit = B; bit >= 0; bit--) {
        vector<vector<long long>> ndp(2, vector<long long>(sz, 0));
        int xbit = (X >> bit) & 1;
        for (int tight = 0; tight <= 1; tight++)
            for (int rem = 0; rem < sz; rem++) {
                if (!dp[tight][rem]) continue;
                int maxb = tight ? xbit : 1;
                for (int b = 0; b <= maxb; b++) {
                    int ntight = tight && (b == xbit);
                    long long nrem = rem | ((long long)b << bit);
                    if (g != 0) nrem = gf2_mod(nrem, g);
                    else nrem = 0;
                    ndp[ntight][nrem] = (ndp[ntight][nrem] + dp[tight][rem]) % MOD;
                }
            }
        dp = ndp;
    }
    long long ans = (dp[0][0] + dp[1][0]) % MOD;
    cout << ans << endl;
}

