struct LinearBasis {
    ll basis[60] = {};
    int r = 0;
    void insert(ll x) {
        for (int i = 59; i >= 0; i--) if (x >> i & 1) {
            if (!basis[i]) { basis[i] = x; r++; return; }
            x ^= basis[i];
        }
    }
    void reduce() {
        for (int i = 59; i >= 0; i--) if (basis[i]) {
            for (int j = i-1; j >= 0; j--) if (basis[j] && (basis[i] >> j & 1))
                basis[i] ^= basis[j];
        }
    }
    // count odd numbers ≤ limit representable
    int count_odd_up_to(ll limit) {
        if (limit < 1) return 0;
        // Collect basis elements with their highest bit
        vector<pair<int, ll>> b;
        for (int i = 0; i < 60; i++) if (basis[i])
            b.push_back({i, basis[i]});
        int m = b.size();
        // DP over bits from high to low, track tight and whether we have odd
        // state: pos (bit index from 59 down to 0), tight, odd
        // We'll iterate bits.
        ll ans = 0;
        // We'll count all numbers ≤ limit with LSB=1
        // Use recursion/backtracking with basis in reduced form
        function<void(int,ll,bool)> dfs = [&](int idx, ll cur, bool tight) {
            if (idx == m) {
                if (cur <= limit && (cur & 1)) ans++;
                return;
            }
            int bit = b[idx].first;
            ll val = b[idx].second;
            // not take
            dfs(idx+1, cur, tight);
            // take if possible
            ll nxt = cur ^ val;
            if (tight) {
                if (nxt <= limit)
                    dfs(idx+1, nxt, tight);
            } else {
                dfs(idx+1, nxt, false);
            }
        };
        // But m can be up to 60 -> exponential. Need smarter counting.
        // Use digit DP over bits of limit.
        // We'll do DP[pos][tight][odd] where pos goes over bits 0..59
        // and we decide which basis element's highest bit to use.
        // Since basis is reduced, we can decide per bit:
        // At bit i, if basis[i] exists, we can choose to xor it.
        // We'll iterate bits from high to low.
        vector<int> bits(60);
        for (int i = 0; i < 60; i++) bits[i] = (limit >> i) & 1;
        // dp[bit][tight][odd]
        ll dp[61][2][2] = {};
        dp[59][1][0] = 1;
        for (int i = 59; i >= 0; i--) {
            for (int tight = 0; tight < 2; tight++) {
                for (int odd = 0; odd < 2; odd++) {
                    ll cur = dp[i][tight][odd];
                    if (!cur) continue;
                    int limit_bit = bits[i];
                    // option: do not use basis[i]
                    for (int take = 0; take <= 1; take++) {
                        if (take && !basis[i]) continue;
                        int new_odd = odd ^ (take && (i==0));
                        int bit_val = (take ? 1 : 0);
                        if (tight && bit_val > limit_bit) continue;
                        int new_tight = tight && (bit_val == limit_bit);
                        dp[i][tight][odd] = 0; // will be overwritten properly
                        // Actually we need to move to next bit
                        // Let's redo: dp[pos][tight][odd] before processing bit pos
                    }
                }
            }
        }
        // Simpler: just enumerate if m <= 20 else use DP
        if (m <= 20) {
            ans = 0;
            for (int mask = 0; mask < (1<<m); mask++) {
                ll val = 0;
                for (int j = 0; j < m; j++) if (mask>>j & 1) val ^= b[j].second;
                if (val <= limit && (val & 1)) ans++;
            }
            return ans;
        }
        // else: DP
        // dp[pos][tight][odd] for bits from high to low
        memset(dp, 0, sizeof(dp));
        dp[60][1][0] = 1; // before any bit
        for (int pos = 59; pos >= 0; pos--) {
            for (int tight = 0; tight < 2; tight++) {
                for (int odd = 0; odd < 2; odd++) {
                    ll cur = dp[pos+1][tight][odd];
                    if (!cur) continue;
                    int limit_bit = (limit >> pos) & 1;
                    for (int take = 0; take <= 1; take++) {
                        if (take && !basis[pos]) continue;
                        int bit_val = take ? 1 : 0;
                        if (tight && bit_val > limit_bit) continue;
                        int ntight = tight && (bit_val == limit_bit);
                        int nodd = odd ^ (take && pos == 0);
                        dp[pos][ntight][nodd] = (dp[pos][ntight][nodd] + cur) % MOD;
                    }
                }
            }
        }
        return (dp[0][0][1] + dp[0][1][1]) % MOD;
    }
};

