static const long long MOD = 998244353;

// Fast power
long long modpow(long long a, long long e) {
    long long r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

// XOR basis over bits [0..60]
struct XorBasis {
    static const int LOG = 61;
    long long b[LOG];
    XorBasis() { memset(b, 0, sizeof(b)); }

    void add(long long x) {
        for (int i = LOG - 1; i >= 0; --i) {
            if (((x >> i) & 1LL) == 0) continue;
            if (!b[i]) {
                b[i] = x;
                return;
            }
            x ^= b[i];
        }
    }

    int rank() const {
        int r = 0;
        for (int i = 0; i < LOG; ++i) if (b[i]) ++r;
        return r;
    }

    // maximum value representable using basis vectors whose highest bit <= limBit
    long long maxWithTopAtMost(int limBit) const {
        long long res = 0;
        for (int i = min(limBit, LOG - 1); i >= 0; --i) {
            if (!b[i]) continue;
            res = max(res, res ^ b[i]);
        }
        return res;
    }

    // count of representable values <= X, using vectors with highest bit <= maxBit
    long long countLE(long long X, int maxBit) const {
        // Build a reduced basis only with pivots <= maxBit.
        vector<long long> piv;
        for (int i = 0; i <= maxBit; ++i) if (b[i]) piv.push_back(b[i]);

        int m = (int)piv.size();
        if (m == 0) return 1; // only 0

        // Transform to row echelon with unique pivots and reduced upper bits.
        // Since original basis already has unique pivots, just collect pivot positions.
        vector<int> pos;
        for (int i = 0; i <= maxBit; ++i) if (b[i]) pos.push_back(i);

        // DP over bits from high to low:
        // Number of representable y <= X in this linear subspace.
        // Standard fact: if subspace projected to lower bits is full for free variables,
        // we can process by checking whether the current bit is constrained by previous choices.
        //
        // Easier method: since basis is in row-echelon by highest bit, count numbers < X lexicographically.
        long long ans = 0;
        long long cur = 0;
        int used = 0; // number of pivot bits processed so far (above current bit)

        // We'll process bits high->low among all bits up to maxBit.
        // For each pivot bit i:
        //   if X_i = 1, we may set y_i = 0 and choose lower pivot bits arbitrarily => add 2^(remaining pivots)
        //   then continue forcing y_i = 1 if possible.
        // For non-pivot bit:
        //   y_i is determined by higher chosen pivots and equals cur_i; if cur_i > X_i impossible, if < then all lower free.
        //
        // To know determined bits under forced prefix, maintain cur as the unique reduced value from chosen higher pivots.
        // Since basis vectors may affect lower bits, when forcing pivot i to 1 we xor b[i].
        int totalPiv = (int)pos.size();
        int processedPiv = 0;

        for (int bit = maxBit; bit >= 0; --bit) {
            bool isPivot = (b[bit] != 0);
            int xb = (X >> bit) & 1LL;
            int yb = (cur >> bit) & 1LL; // current forced bit before deciding pivot if any

            if (isPivot) {
                int rem = totalPiv - processedPiv - 1;
                // We can choose this pivot coefficient to make bit = yb (coef 0) or 1-yb (coef 1).
                // Option making resulting bit 0:
                int bit0 = yb;
                int bit1 = yb ^ 1;

                if (xb == 1) {
                    // choose smaller bit 0 if possible
                    if (bit0 == 0) {
                        ans = (ans + modpow(2, rem)) % MOD;
                    }
                    // continue with equal bit 1
                    if (bit1 == 1) {
                        cur ^= b[bit];
                    } else {
                        // already equal, do nothing
                    }
                } else {
                    // must keep resulting bit 0
                    if (bit0 == 0) {
                        // choose coef 0
                    } else {
                        // must choose coef 1
                        cur ^= b[bit];
                    }
                }
                processedPiv++;
            } else {
                if (yb < xb) {
                    // prefix already smaller, all lower pivot choices are free
                    int rem = totalPiv - processedPiv;
                    ans = (ans + modpow(2, rem)) % MOD;
                    return ans;
                } else if (yb > xb) {
                    return ans;
                }
            }
        }
        // cur itself <= X
        ans = (ans + 1) % MOD;
        return ans;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    long long X;
    cin >> N >> X;
    vector<long long> A(N);
    for (int i = 0; i < N; ++i) cin >> A[i];

    // Key observation:
    // Starting from initial numbers, operations allow generating the smallest set S such that:
    // - A_i in S
    // - x in S => 2x in S
    // - x,y in S => x xor y in S
    //
    // Let V be the linear span over F2 of all numbers {A_i << t | t >= 0}.
    // Then exactly all elements of V are writable.
    //
    // We need count of elements in V not exceeding X.
    //
    // Consider decomposition by lowest set bit.
    // Let v2(z) = index of lowest set bit, and v2(0)=infty.
    // Shifting only increases lowest set bit, xor preserves structure.
    //
    // A cleaner equivalent:
    // Let B be xor-basis of all odd parts of A_i after removing factors of 2,
    // but available at every shift >= original trailing zeros.
    //
    // Simpler constructive characterization:
    // Build basis from all A_i. Since doubling is allowed, any basis vector can be shifted left arbitrarily.
    // Process bits from low to high:
    // define dp over minimal bit. This collapses to:
    // For each k, the set of writable numbers divisible by 2^k and reduced by 2^k
    // is the span of {A_i >> k | A_i divisible by 2^k}, together with all their left shifts.
    //
    // An efficient way:
    // For each k up to 60, consider numbers floor(A_i / 2^k) where lower k bits are zero, i.e. A_i >> k for A_i % 2^k == 0.
    // Their xor span gives exactly the possible values of y where number = y << k and lowest k bits zero.
    // To count all numbers <= X, partition by exact trailing-zero threshold using highest relevant k.
    //
    // Let F(k) = span of {A_i >> k | (A_i & ((1<<k)-1)) == 0 }.
    // Then writable numbers divisible by 2^k are exactly {z << k | z in F(k)}.
    // Count numbers with exact valuation k by divisible-by-2^k minus divisible-by-2^(k+1),
    // plus zero separately.
    //
    // Since X <= 1e18 scale (implied by long long), bits up to 60 suffice.

    long long answer = 1; // zero is always writable as x xor x if any x exists; if N>=1 yes. Also if initial has 0. Problem has N integers, assume N>=1.
    // But to avoid assumptions, with N>=1 zero is writable.

    // Count nonzero numbers by exact trailing zeros.
    for (int k = 0; k <= 60; ++k) {
        XorBasis basisK, basisK1;
        for (long long a : A) {
            if ((a & ((1LL << min(k, 62)) - 1)) == 0) {
                basisK.add(a >> k);
            }
            if (k < 60 && (a & ((1LL << (k + 1)) - 1)) == 0) {
                basisK1.add(a >> (k + 1));
            }
        }

        long long lim = X >> k;
        if (lim == 0) continue;

        long long cntDivK = basisK.countLE(lim, 60 - k);
        long long cntDivK1 = 0;
        if (k < 60) cntDivK1 = basisK1.countLE(X >> (k + 1), 60 - (k + 1));
        else cntDivK1 = 1; // only 0

        // Remove zero from exact class counts naturally by subtraction.
        long long exact = (cntDivK - cntDivK1) % MOD;
        if (exact < 0) exact += MOD;
        answer += exact;
        if (answer >= MOD) answer -= MOD;
    }

    cout << answer % MOD << '\n';
    return 0;
}

import java.util.*;

public class Main {
    static final int MOD = 998244353;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        long X = sc.nextLong();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) {
            A[i] = sc.nextLong();
        }

        // Build basis from all A_i * 2^k ≤ X
        List<Long> vals = new ArrayList<>();
        for (long a : A) {
            long v = a;
            while (v <= X) {
                vals.add(v);
                if (v == 0) break;
                v <<= 1;
            }
        }

        // Linear basis insertion
        long[] basis = new long[60];
        int size = 0;
        for (long v : vals) {
            long x = v;
            for (int b = 59; b >= 0; b--) {
                if ((x & (1L << b)) == 0) continue;
                if (basis[b] == 0) {
                    basis[b] = x;
                    size++;
                    break;
                }
                x ^= basis[b];
            }
        }

        // Build reduced basis (row-echelon form)
        List<Long> basisList = new ArrayList<>();
        for (int b = 0; b < 60; b++) {
            if (basis[b] != 0) {
                basisList.add(basis[b]);
            }
        }

        // Count numbers ≤ X
        long ans = countLE(basisList, X);
        System.out.println(ans % MOD);
    }

    static long countLE(List<Long> basis, long limit) {
        int m = basis.size();
        // Sort by highest bit descending
        Collections.sort(basis, (a, b) -> Long.compare(b, a));
        long ans = 0;
        long cur = 0;
        for (int i = 0; i < m; i++) {
            long b = basis.get(i);
            if ((cur ^ b) <= limit) {
                cur ^= b;
                ans = (ans + pow2(m - i - 1)) % MOD;
            }
        }
        // Include zero
        ans = (ans + 1) % MOD;
        return ans;
    }

    static long pow2(int e) {
        long res = 1, base = 2;
        while (e > 0) {
            if ((e & 1) == 1) res = (res * base) % MOD;
