public class Main {
    static final long MOD = 998244353L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long X = fs.nextLong();
        long[] A = new long[N];
        for (int i = 0; i < N; i++) A[i] = fs.nextLong();

        int m = Math.max(1, 64 - Long.numberOfLeadingZeros(X)); // bits 0..m-1 relevant
        long mask = (m == 64) ? -1L : ((1L << m) - 1);

        // Build xor basis from all shifts truncated to m bits.
        long[] basisPivot = new long[64];
        for (long a : A) {
            long v = a & mask;
            for (int s = 0; s < m && v != 0; s++) {
                insertBasis(basisPivot, v);
                if ((v & (1L << (m - 1))) != 0 && m < 64) {
                    // next shift will overflow beyond mask
                    v = (v << 1) & mask;
                } else {
                    v = (v << 1) & mask;
                }
            }
        }

        ArrayList<Long> list = new ArrayList<>();
        for (int i = 63; i >= 0; i--) if (basisPivot[i] != 0) list.add(basisPivot[i]);
        int r = list.size();
        long[] b = new long[r];
        for (int i = 0; i < r; i++) b[i] = list.get(i);

        long[] pow2 = new long[r + 1];
        pow2[0] = 1;
        for (int i = 1; i <= r; i++) pow2[i] = (pow2[i - 1] * 2) % MOD;

        long ans = 0;
        int[] pos = new int[m];
        int[] val = new int[m];
        int fixed = 0;

        for (int bit = m - 1; bit >= 0; bit--) {
            if (((X >>> bit) & 1L) != 0) {
                pos[fixed] = bit;
                val[fixed] = 0;
                ans += countSolutions(b, r, pos, val, fixed + 1, pow2);
                ans %= MOD;

                pos[fixed] = bit;
                val[fixed] = 1;
                if (!isConsistent(b, r, pos, val, fixed + 1)) {
                    System.out.println(ans % MOD);
                    return;
                }
                fixed++;
            } else {
                pos[fixed] = bit;
                val[fixed] = 0;
                if (!isConsistent(b, r, pos, val, fixed + 1)) {
                    System.out.println(ans % MOD);
                    return;
                }
                fixed++;
            }
        }

        // X itself
        ans++;
        ans %= MOD;
        System.out.println(ans);
    }

    static void insertBasis(long[] basis, long x) {
        long v = x;
        for (int i = 63; i >= 0; i--) {
            if (((v >>> i) & 1L) == 0) continue;
            if (basis[i] == 0) {
                basis[i] = v;
                return;
            }
            v ^= basis[i];
        }
    }

    static boolean isConsistent(long[] b, int r, int[] pos, int[] val, int k) {
        return solveRank(b, r, pos, val, k)[1] >= 0;
    }

    static long countSolutions(long[] b, int r, int[] pos, int[] val, int k, long[] pow2) {
        int[] res = solveRank(b, r, pos, val, k);
        int rank = res[0];
        int ok = res[1];
        if (ok < 0) return 0;
        return pow2[r - rank];
    }

    // returns {rank, 1} if consistent, {rank, -1} if inconsistent
    static int[] solveRank(long[] b, int r, int[] pos, int[] val, int k) {
        if (k == 0) return new int[]{0, 1};
        long[] rows = new long[k];
        int[] rhs = new int[k];
        for (int i = 0; i < k; i++) {
            long row = 0;
            int p = pos[i];
            for (int j = 0; j < r; j++) {
                if (((b[j] >>> p) & 1L) != 0) row |= 1L << j;
            }
            rows[i] = row;
            rhs[i] = val[i];
        }

        int rank = 0;
        for (int col = 0; col < r && rank < k; col++) {
            int pivot = -1;
            for (int i = rank; i < k; i++) {
                if (((rows[i] >>> col) & 1L) != 0) {
                    pivot = i;
                    break;
                }
            }
            if (pivot == -1) continue;
            long tmp = rows[rank]; rows[rank] = rows[pivot]; rows[pivot] = tmp;
            int tv = rhs[rank]; rhs[rank] = rhs[pivot]; rhs[pivot] = tv;

            for (int i = 0; i < k; i++) {
                if (i != rank && ((rows[i] >>> col) & 1L) != 0) {
                    rows[i] ^= rows[rank];
                    rhs[i] ^= rhs[rank];
                }
            }
            rank++;
        }

        for (int i = rank; i < k; i++) {
            if (rows[i] == 0 && rhs[i] != 0) return new int[]{rank, -1};
        }
        return new int[]{rank, 1};
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
